def analyze_differences(inputs, outputs):
    """Analyze what transformations are needed"""
    print("Detailed difference analysis:")
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        print(f"\nPair {i}: '{inp}' -> '{outp}'")
        if inp == outp:
            print("  No change")
            continue

        # Check if we can find simple replacements
        min_len = min(len(inp), len(outp))

        # Look for character substitutions
        for j in range(min_len):
            if j < len(inp) and j < len(outp) and inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")

        # Check if lengths differ
        if len(inp) != len(outp):
            print(f"  Length change: {len(inp)} -> {len(outp)}")

